    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the first four values
    # fib4[i] will store fib4(i)
    fib4_sequence = [0, 0, 2, 0]

    # Calculate subsequent values iteratively
    for i in range(4, n + 1):
        # fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
        next_val = fib4_sequence[i-1] + fib4_sequence[i-2] + fib4_sequence[i-3] + fib4_sequence[i-4]
        fib4_sequence.append(next_val)

    return fib4_sequence[n]
